	public void removeFromCompetencyRatings( RemoveCompetencyRatingsFromCompetencyCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromCompetencyRatings(command.getCompetencyId(), command.getRemoveFrom());
	}




